from heapq import heappush, heappop
from collections import defaultdict

def maximize_defense_score(n, m, k, castles, portals):
    graph = defaultdict(list)
    for u, v in portals:
        graph[u].append(v)

    dp = [[-1] * (k + 1) for _ in range(n + 1)]
    dp[0][k] = 0

    for i in range(1, n + 1):
        a, b, c = castles[i - 1]
        for j in range(k + 1):
            if dp[i - 1][j] != -1:
                if j >= a:
                    dp[i][j - a] = max(dp[i][j - a], dp[i - 1][j])
                if j + b <= k:
                    dp[i][j + b] = max(dp[i][j + b], dp[i - 1][j] + c)

        for j in range(k + 1):
            if dp[i][j] != -1:
                for v in graph[i]:
                    if j > 0:
                        dp[i][j - 1] = max(dp[i][j - 1], dp[i][j])

    return max(dp[n])

def main():
    n, m, k = map(int, input().split())
    castles = [list(map(int, input().split())) for _ in range(n)]
    portals = [list(map(int, input().split())) for _ in range(m)]

    result = maximize_defense_score(n, m, k, castles, portals)
    print(result)

if __name__ == "__main__":
    main()
